  "mk.starth": "సెల్లర్ పోర్టల్ నుండి మీరు డౌన్‌లోడ్ చేసిన పేఅవుట్ (సెటిల్‌మెంట్) ఫైల్‌ను Excel లేదా CSV గా తెరవండి. ఇది ఈ బ్రౌజర్‌లో మాత్రమే చదవబడుతుంది.",
  "mk.s1": "ఫైల్ తెరవండి. టూల్ హెడింగ్‌ల ద్వారా కాలమ్‌లను కనుగొంటుంది; తప్పుగా ఉన్న కాలమ్‌ను మార్చండి.",
  "mk.s2": "ప్రతి ఆర్డర్ మీ సేవ్ చేసిన ఇన్‌వాయిస్‌లతో ఆర్డర్ ఐడీ ద్వారా, తర్వాత మొత్తం మరియు తేదీ ద్వారా సరిపోల్చబడుతుంది.",
  "mk.s3": "రిటర్న్‌లు, ఫీజులు, TCS మరియు TDS, మీరు బిల్లు చేయని ఆర్డర్‌లు, పేఅవుట్ సరిపోతుందా లేదా చూడండి.",
  "mk.layout": "ప్రతి మార్కెట్‌ప్లేస్ ఫైల్ లేఅవుట్ ఈ టూల్‌కు తెలియదు, అది అప్పుడప్పుడు మారుతుంది. మీ ఫైల్ సరిగ్గా చదవబడకపోతే, “ఏ కాలమ్ ఏది” కింద కాలమ్‌లను చేతితో ఎంచుకోండి, లేదా అది చదివే రెండు రూపాలు చూడటానికి ఉదాహరణ ఫైల్ డౌన్‌లోడ్ చేయండి.",
  "mk.readfail": "ఈ ఫైల్ చదవలేకపోయాం. Excel (.xlsx) లేదా CSV ఫైల్ వాడండి.",
