  "mk.tcsl": "TCS (section 52 CGST)",
  "mk.tdsl": "TDS (section 194-O)",
  "mk.taxnote": "TCS అమ్మకాల విలువ నుండి రిటర్న్‌లు తీసేసి, GST లేకుండా చెక్ చేయబడుతుంది. TDS మొత్తం అమ్మకాల నుండి రిటర్న్‌లు తీసేసి చెక్ చేయబడుతుంది. చిన్న సెల్లర్ల ఆర్డర్‌లకు TDS మినహాయింపు ఉండవచ్చు, సెల్లర్‌కు తక్కువ రేటు సర్టిఫికెట్ ఉండవచ్చు. క్లెయిమ్ చేసే ముందు GST పోర్టల్‌లో TCS క్రెడిట్ (TCS credit received), Form 26AS లేదా AIS లో TDS చెక్ చేయండి.",
