  "pr.reset": "సాధారణ విలువలకు తిరిగి వెళ్ళండి",
  "pr.rates_pf": "సాధారణ EPF రూల్స్ ప్రకారం సెట్ చేయబడింది: నెలకు వేతన పరిమితి ₹25,000 (17 సెప్టెంబర్ 2026 నుండి), ఉద్యోగి 12%, పెన్షన్ (EPS) 8.33%, EDLI 0.5%, అడ్మినిస్ట్రేషన్ 0.5% కనీసం ₹500 తో. చెల్లించే ముందు EPFO సైట్‌లో చెక్ చేయండి.",
  "pr.rates_esi": "వేతనంపై ఉద్యోగి 0.75% మరియు యజమాని 3.25%, ఒక్కొక్కటి తర్వాతి రూపాయికి పైకి రౌండ్ చేయబడుతుంది (Social Security (Central) Rules, 2026, rule 19). వేతన పరిమితి నెలకు ₹21,000: ప్రస్తుత పరిమితిని ESIC సైట్‌లో చెక్ చేయండి. రోజు వేతనం ₹176 లేదా అంతకంటే తక్కువ అయితే ఉద్యోగి వాటా లేదు (ESIC contribution page).",
