  "pr.pfintro": "నెల జీతం స్లిప్‌ల నుండి EPFO unified portal కోసం ECR టెక్స్ట్ ఫైల్ మరియు చలాన్ మొత్తాలు తయారవుతాయి. ముందుగా స్లిప్‌లు చేయండి (జీతం ట్యాబ్); స్లిప్ లేని ఉద్యోగులు కింద చూపబడతారు.",
  "pr.unver_pf": "అప్‌లోడ్ చేసే ముందు చెక్ చేయండి: ఇది తయారు చేసినప్పుడు (14 నవంబర్ 2026) EPFO సొంత ఫైల్-స్ట్రక్చర్ డాక్యుమెంట్ తెరవలేకపోయాం. 11 ఫీల్డ్‌లు, వాటి క్రమం పేరోల్ సాఫ్ట్‌వేర్ తయారీదారులు ప్రచురించిన దాని ప్రకారం ఉన్నాయి. ఫైల్‌ను EPFO పోర్టల్ ECR పేజీలో అప్‌లోడ్ చేయండి; పోర్టల్ ఏదైనా లైన్‌ను తిరస్కరిస్తే కారణం చెబుతుంది.",
