  "it.plan_h": "మీ పుస్తకాల నుండి సంవత్సరపు ఆదాయాన్ని అంచనా వేయండి, రెండు రెజీమ్‌లలో టాక్స్ చూడండి, నాలుగు అడ్వాన్స్ టాక్స్ వాయిదాలను ప్లాన్ చేయండి. ఏ అంకెనైనా మార్చండి: మీ మార్పులు ఈ బిజినెస్, సంవత్సరం కోసం ఈ పరికరంలో ఉంచబడతాయి.",
