  "it.m_senior": "బిజినెస్ లేదా ప్రొఫెషనల్ ఆదాయం లేని 60 లేదా ఎక్కువ వయస్సున్న నివాసి అడ్వాన్స్ టాక్స్ కట్టనక్కర్లేదు (section 403(3)). రిటర్న్ ఫైల్ చేసేటప్పుడు బ్యాలెన్స్ కట్టండి.",
  "it.m_below": "TDS తర్వాత టాక్స్ {n}, ₹10,000 కంటే తక్కువ, కాబట్టి అడ్వాన్స్ టాక్స్ లేదు (section 404). రిటర్న్ ఫైల్ చేసేటప్పుడు బ్యాలెన్స్ కట్టండి.",
  "it.m_pres": "ప్రిజంప్టివ్ స్కీమ్‌లో మొత్తం అడ్వాన్స్ టాక్స్ 15 మార్చి లోపు కట్టాలి (section 408(2)).",
  "it.m_sur": "మీ ఆదాయం ₹50 లక్షలు దాటింది: సర్‌చార్జ్ టైప్ చేయండి, అది ఇక్కడ లెక్కించబడదు.",
  "it.m_past": "ఈ సంవత్సరం ముగిసింది. 31 మార్చి తర్వాత కట్టిన అడ్వాన్స్ టాక్స్ ఈ సంవత్సరానికి అడ్వాన్స్ టాక్స్‌గా లెక్కించబడదు; తక్కువ కట్టితే ఎంత ఖర్చవుతుందో కింది వడ్డీ చూపిస్తుంది.",
