  "it.basis": "ఈ అంకెలు దేని ఆధారంగా ఉన్నాయి ({d} నాటికి)",
  "it.b1": "రేట్లు ({d} నాటికి), టాక్స్ సంవత్సరం 2026-27: కొత్త రెజీమ్ ₹4 లక్షల వరకు నిల్, ₹8 లక్షల వరకు 5%, ₹12 లక్షల వరకు 10%, ₹16 లక్షల వరకు 15%, ₹20 లక్షల వరకు 20%, ₹24 లక్షల వరకు 25%, ఆపై 30%; ₹12 లక్షల వరకు ఆదాయానికి టాక్స్ లేకుండా రిబేట్, కొంచెం పైన మార్జినల్ రిలీఫ్; జీతంపై స్టాండర్డ్ డిడక్షన్ ₹75,000. పాత రెజీమ్: ₹2.5 లక్షల వరకు నిల్ (60 ఏళ్లకు ₹3 లక్షలు, 80 ఏళ్లకు ₹5 లక్షలు), ₹5 లక్షల వరకు 5%, ₹10 లక్షల వరకు 20%, ఆపై 30%; ₹5 లక్షల వరకు రిబేట్ ₹12,500; స్టాండర్డ్ డిడక్షన్ ₹50,000. ఇవి జీతం స్లిప్ టూల్ ఇప్పటికే వాడే రేట్లు; ఈ బిల్డ్‌లో Finance Act నుండి మళ్ళీ చదవలేదు, కాబట్టి చెక్ చేయండి.",
  "it.b2": "అడ్వాన్స్ టాక్స్ (Income-tax Act 2025, sections 403 నుండి 408): TDS తర్వాత టాక్స్ ₹10,000 లేదా ఎక్కువ అయితే కట్టాలి; 15 జూన్ లోపు 15%, 15 సెప్టెంబర్ లోపు 45%, 15 డిసెంబర్ లోపు 75%, 15 మార్చి లోపు మొత్తం; ప్రిజంప్టివ్ టాక్స్‌పేయర్ 15 మార్చి లోపు మొత్తం కడతారు; 31 మార్చి వరకు కట్టింది ఆ సంవత్సరానికి లెక్కించబడుతుంది; బిజినెస్ ఆదాయం లేని 60 లేదా ఎక్కువ వయస్సున్న నివాసికి మినహాయింపు.",
  "it.b3": "వడ్డీ: section 424 (పాత 234B) టాక్స్‌లో 90% కంటే తక్కువ కట్టినప్పుడు తక్కువైన మొత్తంపై నెలకు లేదా నెలలో భాగానికి 1%; section 425 (పాత 234C) మొదటి మూడు వాయిదాలలో ప్రతిదాని తక్కువపై 3% (15 జూన్ లోపు 12%, 15 సెప్టెంబర్ లోపు 36% కట్టితే లేదు), మార్చి తక్కువపై 1%.",
  "it.b5": "పుస్తకాల లాభం టాక్స్ పడే లాభం కాదు: Act ప్రకారం డిప్రిసియేషన్, అనుమతించని ఖర్చులు, ప్రిజంప్టివ్ రూల్స్ దాన్ని మారుస్తాయి. ఈ ప్లాన్, డేటా షీట్ మీ అకౌంటెంట్‌కు ఇవ్వండి.",
  "it.b6": "లెక్కించబడనివి: సర్‌చార్జ్, ప్రత్యేక రేట్లలో కేపిటల్ గెయిన్స్, విదేశీ టాక్స్ రిలీఫ్, మైనర్ ఆదాయంపై టాక్స్, ఆలస్యంగా ఫైల్ చేసినందుకు వడ్డీ.",
  "it.b7": "ఏదీ ఫైల్ చేయబడదు, మీ పుస్తకాలలో ఏదీ పోస్ట్ చేయబడదు.",
  "it.itr_h": "ఏ రిటర్న్ ఫారమ్ సరిపోతుంది, ఎందుకు, ఏ పేపర్లు రెడీగా ఉంచాలి అని చూడటానికి కొన్ని ప్రశ్నలకు జవాబు ఇవ్వండి.",
  "it.use_form": "సరిపోయే ITR ఫారమ్: {f}",
